import{_ as o,o as t,c as a,ao as i}from"./chunks/framework.DagBLaYp.js";const u=JSON.parse('{"title":"One model across simulation, fitting and prediction","description":"","frontmatter":{},"headers":[],"relativePath":"model-workflow.md","filePath":"model-workflow.md","lastUpdated":null}'),s={name:"model-workflow.md"};function n(r,e,d,c,l,m){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="One-model-across-simulation,-fitting-and-prediction" tabindex="-1">One model across simulation, fitting and prediction <a class="header-anchor" href="#One-model-across-simulation,-fitting-and-prediction" aria-label="Permalink to &quot;One model across simulation, fitting and prediction {#One-model-across-simulation,-fitting-and-prediction}&quot;">​</a></h1><p>A <code>CrystallisationSystem</code> describes material properties and solubility. <code>LysozymeSystem()</code> is an ordinary instance with explicit lysozyme defaults. <code>KineticModel</code> binds one law to named values. Calling a built-in law with all of its parameter names, such as <code>EmpiricalGrowth(growth_coefficient = 1e-9, growth_order = 2.0)</code>, returns a bound <code>KineticModel</code>. <code>CrystallisationModel(system; nucleation, growth, dissolution, aggregation, breakage)</code> collects the five slots; omitted optional slots use no-op laws.</p><p><code>RunConditions</code> describe one run: temperature, initial concentration, extra solvent values, an optional seed and the reactor operation. <code>simulate(model, conditions; solver, saveat)</code> returns a physical solution. <code>CrystallisationProblem(model, conditions; solver)</code> builds the configured problem explicitly. Advanced callers can still obtain a generated SciML ODE, control callbacks and convert its solution using the solver interfaces.</p><p>A <code>CrystallisationExperiment</code> stores measured observables and the <code>RunConditions</code> it was run under. A <code>FromObservation(:name)</code> placeholder in those conditions is read from the experiment&#39;s time-zero observation of that observable. The initial concentration defaults to <code>FromObservation(:concentration)</code>, so a direct simulation must supply a number. Placeholders may stand for the concentration, another solvent value or any numeric seed field. Initialising measurements are excluded from scoring. Every other observable retains its own time grid.</p><p><code>OptimisationSpec</code>, <code>BayesianSpec</code> and <code>ABCSpec</code> separately describe studies. Their nested names select kinetic parameters; unlisted values remain fixed. No initial condition, material property or noise parameter can be selected. <code>prepare_fit(model, experiments, spec; solver, mode, problem_options)</code> resolves names and constructs solve templates once (<code>mode</code> is <code>TransientMode()</code> or <code>SteadyMode(SteadyStateOptions(...))</code>); <code>loss(prepared, values)</code> exposes the selected-vector objective for advanced users and autodiff. <code>fit(prepared; parallel=EnsembleSerial())</code> runs the study; <code>parallel = EnsembleThreads()</code> (also accepted by <code>prepare_fit</code>) threads either the candidates (Metaheuristics population, ABC particles, several NUTS chains) or the experiments of each loss evaluation (Optimization.jl solvers, one NUTS chain), never both.</p><p><code>fit</code> returns a <code>FitResult</code> for optimisation or <code>InferenceResult</code> for sampling. An optimisation result contains a new fitted model, named estimates, observable objectives and the native backend result. Input models are not mutated.</p><p><code>ParameterSamples</code> carries joint kinetic draws in rows and samples in columns, with common sample IDs. <code>predict(result)</code> repeats the fitted experiments, and <code>predict(result, runs)</code> takes new experiments or <code>RunConditions</code>; both reuse the fit&#39;s solver, mode and options. <code>predict(model, runs, samples; solver)</code> propagates user-supplied draws and requires an explicit solver. Each draw is reused across all requested runs. <code>PredictionResult.ensembles</code> retains each run&#39;s trajectories and diagnostics. Physical summaries require explicit <code>skip_failed=true</code> to exclude failed solves. Supplied additive noise can be drawn with <code>measurement_samples</code>; it never changes the ODE or estimates noise parameters.</p><p><a href="./simulation">Simulation</a>, <a href="./parameter-estimation">fitting</a> and <a href="./uq-ensembles">prediction</a> give complete examples.</p>',8)])])}const h=o(s,[["render",n]]);export{u as __pageData,h as default};
